class E2{constructor(){this.a={};this.p={};this.h=[]}
sp(p){this.p=p}
ga(){const s=new Set();for(const q of Q)if(q.cd&&this.a[q.id]!==undefined&&this.a[q.id]<q.cd.lt)s.add(q.cd.sh);return Q.filter(q=>!q.iS||s.has(q.id)).sort((a,b)=>{const da=D.findIndex(d=>d.id===a.dm),db=D.findIndex(d=>d.id===b.dm);return da!==db?da-db:a.o-b.o})}
nx(){for(const q of this.ga())if(this.a[q.id]===undefined)return q;return null}
ans(id,v){this.a[id]=v;if(!this.h.includes(id))this.h.push(id);this.sv()}
un(id){delete this.a[id];const q=Q.find(p=>p.id===id);if(q&&q.cd)delete this.a[q.cd.sh];this.sv()}
bk(){if(this.h.length<1)return null;const c=this.h.pop();this.un(c);if(this.h.length>0){const p=this.h[this.h.length-1];this.un(p)}return true}
pg(){const a=this.ga(),r=a.filter(q=>this.a[q.id]!==undefined).length;return{t:a.length,d:r,p:Math.round(r/a.length*100)}}
dp(did){const a=this.ga().filter(q=>q.dm===did),r=a.filter(q=>this.a[q.id]!==undefined).length;return{t:a.length,d:r,p:a.length?Math.round(r/a.length*100):0}}
sc(){const s={};let tw=0,mw=0;for(const d of D){const qs=this.ga().filter(q=>q.dm===d.id);let sm=0,mx=0;for(const q of qs){const v=this.a[q.id];if(v!==undefined){sm+=v*(q.w||1);mx+=3*(q.w||1)}}s[d.id]=mx?Math.round(sm/mx*100):0;tw+=s[d.id]*d.w;mw+=100*d.w}return{g:mw?Math.round(tw/mw*100):0,d:s}}
ml(s){if(s<=20)return{n:0,nm:'Sin protección',cl:'m0',c:'#EF4444'};if(s<=40)return{n:1,nm:'Reactivo',cl:'m1',c:'#F59E0B'};if(s<=60)return{n:2,nm:'En desarrollo',cl:'m2',c:'#FBBF24'};if(s<=80)return{n:3,nm:'Gestionado',cl:'m3',c:'#00B894'};return{n:4,nm:'Optimizado',cl:'m4',c:'#10B981'}}
fl(){const f=[];for(const q of Q)if(q.fl&&q.fl.length&&this.a[q.id]!==undefined&&q.fl.includes(this.a[q.id]))f.push({id:q.id,dm:q.dm,q:q.q,ar:q.ar,v:this.a[q.id]});return f}
pl(){const sc=this.sc(),p=[];for(const d of D){const s=sc.d[d.id];if(s>=80)continue;let rk='MEDIO',rc='rme';if(s<=30){rk='CRÍTICO';rc='rc'}else if(s<=55){rk='ALTO';rc='ra'}p.push({d,s,rk,rc,ml:this.ml(s),ac:A[d.id].ac,ev:A[d.id].e})}p.sort((a,b)=>a.s-b.s);return p}
cl2(){return CL.map(c=>{let t=0,n=0;for(const id of c.qs){const v=this.a[id];if(v!==undefined){t+=v;n++}}if(!n)return{...c,st:'gray',lb:'Sin datos',avg:0};const avg=t/n;let st='red',lb='No cumple';if(avg>=c.tV){st='green';lb='Cumple'}else if(avg>=c.tY){st='yellow';lb='Parcial'}return{...c,st,lb,avg}})}
sv(){try{localStorage.setItem('d360v3',JSON.stringify({a:this.a,p:this.p,h:this.h,ts:Date.now()}))}catch(e){}}
ld(){try{const d=JSON.parse(localStorage.getItem('d360v3'));if(d){this.a=d.a||{};this.p=d.p||{};this.h=d.h||[];return true}}catch(e){}return false}
rs(){this.a={};this.p={};this.h=[];try{localStorage.removeItem('d360v3')}catch(e){}}
}

