function pk(el,qid,v){document.querySelectorAll('.opt').forEach(o=>o.classList.remove('sel'));el.classList.add('sel');cs=v;document.getElementById('bnx').disabled=false;const q=Q.find(p=>p.id===qid),fb=document.getElementById('fb');q.fl&&q.fl.includes(v)?fb.classList.add('show'):fb.classList.remove('show')}
