// T1 Radar
h+=`<div class="tp active" id="t1"><div class="rs"><h3><div class="ic" style="background:var(--teal-soft)"><i data-lucide="radar" style="color:var(--teal)"></i></div>Perfil por dimensión</h3><div class="rw"><canvas id="rcv"></canvas></div><div class="dg">${D.map(d=>{const s=sc.d[d.id],m=en.ml(s);return`<div class="dimc"><div class="db" style="background:${d.c}"></div><div class="di"><div class="dn">${d.n}</div><div class="ds" style="color:${m.c}">${s}%</div></div></div>`}).join('')}</div></div></div>`;

// T2 Brechas
const br=D.map(d=>({d,s:sc.d[d.id]})).sort((a,b)=>a.s-b.s).filter(b=>b.s<80);
