if(!br.length)h+='<p style="color:var(--text-muted);font-size:.9rem">✓ Sin brechas significativas.</p>';
else for(const b of br){const lc=b.s<=30?'crit':b.s<=55?'high':'med',ln=b.s<=30?'Crítico':b.s<=55?'Alto':'Medio',co=b.s<=30?'var(--danger)':b.s<=55?'var(--warning)':'#60A5FA';h+=`<div class="br"><div class="bd ${lc}"></div><div class="bm"><div class="bn2">${b.d.n}</div><div class="ba">${b.d.a} · Riesgo ${ln}</div></div><div class="bv" style="color:${co}">${b.s}%</div></div>`}
h+=`</div></div>`;

// T3 Plan
h+=`<div class="tp" id="t3"><div class="rs"><h3><div class="ic" style="background:var(--teal-soft)"><i data-lucide="list-checks" style="color:var(--teal)"></i></div>Plan de acción priorizado</h3>`;
if(!pl.length)h+='<p style="color:var(--text-muted);font-size:.9rem">✓ Todas las dimensiones superan el objetivo.</p>';
else for(const it of pl){h+=`<div class="pc2"><div class="ph"><h4><i data-lucide="${it.d.ic}" style="color:${it.d.c}"></i>${it.d.n}</h4><span class="rt ${it.rc}">Riesgo ${it.rk}</span></div><div class="pm"><span><i data-lucide="bar-chart-3"></i>Actual: ${it.s}%</span><span><i data-lucide="target"></i>Objetivo: 80%</span><span><i data-lucide="book-open"></i>${it.d.a}</span></div>${it.ac.map((a,i)=>`<div class="stpr"><div class="sn">${i+1}</div><div class="sb"><div class="st">${a.t}</div><div class="sm">Plazo: ${a.p} · Responsable: ${a.r}</div></div></div>`).join('')}<div class="pe"><strong>Evidencia:</strong> ${it.ev}</div></div>`}
h+=`</div></div>`;

// T4 Checklist
h+=`<div class="tp" id="t4"><div class="rs"><h3><div class="ic" style="background:var(--warning-soft)"><i data-lucide="check-square" style="color:var(--warning)"></i></div>Semáforo Ley 21.719</h3>`;
for(const c of cl){const ic=c.st==='green'?'check':(c.st==='yellow'||c.st==='gray')?'minus':'x',cc=c.st==='green'?'clg':c.st==='yellow'?'cly':c.st==='gray'?'clgy':'clrd',co=c.st==='green'?'var(--success)':c.st==='yellow'?'var(--warning)':c.st==='gray'?'var(--text-muted)':'var(--danger)';h+=`<div class="clr"><div class="cli ${cc}"><i data-lucide="${ic}"></i></div><div class="clt">${c.ob}<span class="ca">${c.ar}</span></div><div class="cls" style="color:${co}">${c.lb}</div></div>`}
h+=`</div></div>`;

// T5 Flags
if(fl.length){h+=`<div class="tp" id="t5"><div class="rs"><h3><div class="ic" style="background:var(--danger-soft)"><i data-lucide="flag" style="color:var(--danger)"></i></div>Alertas críticas</h3>`;for(const f of fl){const d=D.find(x=>x.id===f.dm);h+=`<div class="br"><div class="bd crit"></div><div class="bm"><div class="bn2" style="font-size:.84rem">${f.q}</div><div class="ba">${d.n} · ${f.ar}</div></div></div>`}h+=`</div></div>`}

