function rg(s,c){const cv=document.getElementById('gc');if(!cv)return;const x=cv.getContext('2d');cv.width=180;cv.height=180;const cx=90,cy=98,r=72,sa=Math.PI*.8,ea=Math.PI*2.2,an=sa+(ea-sa)*(s/100);x.beginPath();x.arc(cx,cy,r,sa,ea);x.strokeStyle='rgba(255,255,255,.1)';x.lineWidth=10;x.lineCap='round';x.stroke();x.beginPath();x.arc(cx,cy,r,sa,an);x.strokeStyle=c;x.lineWidth=10;x.lineCap='round';x.stroke()}
function rr(ds){const cv=document.getElementById('rcv');if(!cv)return;new Chart(cv,{type:'radar',data:{labels:D.map(d=>d.n),datasets:[{data:D.map(d=>ds[d.id]||0),backgroundColor:'rgba(0,184,148,.12)',borderColor:'#00B894',borderWidth:2,pointBackgroundColor:D.map(d=>d.c),pointBorderColor:'#fff',pointBorderWidth:2,pointRadius:5}]},options:{responsive:true,maintainAspectRatio:true,scales:{r:{beginAtZero:true,max:100,ticks:{stepSize:25,font:{size:10},backdropColor:'transparent'},pointLabels:{font:{size:11,family:"'Plus Jakarta Sans',sans-serif"},color:'#2D3748'},grid:{color:'rgba(0,0,0,.05)'},angleLines:{color:'rgba(0,0,0,.05)'}}},plugins:{legend:{display:false}}}})}
function sm(){const p=en.p,sc=en.sc(),m=en.ml(sc.g),s=encodeURIComponent(`Resultado D360° — ${p.nombre}`),b=encodeURIComponent(`D360° Privacy Assessment\nEmpresa: ${p.nombre}\nSector: ${p.sector}\nScore: ${sc.g}%\nNivel: ${m.nm}\n\nDescargue el PDF desde la herramienta.\n\nAlignData — aligndata.cl`);window.open(`mailto:${p.email||''}?subject=${s}&body=${b}`)}
function ra(){en.rs();cs=null;['f1','f4'].forEach(id=>document.getElementById(id).value='');['f2','f3'].forEach(id=>document.getElementById(id).value='');ss('s1')}
document.addEventListener('DOMContentLoaded',()=>{lucide.createIcons();if(en.ld()&&Object.keys(en.a).length&&en.p.nombre){if(confirm('Tiene un diagnóstico en progreso. ¿Desea continuarlo?')){ss('s2');rq()}else en.rs()}});
